def greedy(prompt, n=8):
    ids = tok(prompt, return_tensors='pt').input_ids.to(model.device)
    out = ids
    with torch.no_grad():
        for _ in range(n):
            lg = model(out).logits[0, -1].float()
            out = torch.cat([out, torch.tensor([[int(lg.argmax())]], device=out.device)], 1)
    return tok.decode(out[0, ids.shape[1]:])

